function countOfPairs(nums) {
  const MOD = 1_000_000_007;
  const maxValue = Math.max(...nums);
  let dp = new Array(maxValue + 1).fill(0);
  for (let j = 0; j <= nums[0]; j++) {
    dp[j] = 1;
  }
  for (let i = 1; i < nums.length; i++) {
    const shift = Math.max(0, nums[i] - nums[i - 1]);
    const prefix = new Array(maxValue + 1).fill(0);
    prefix[0] = dp[0];
    for (let k = 1; k <= maxValue; k++) {
      prefix[k] = (prefix[k - 1] + dp[k]) % MOD;
    }
    const next = new Array(maxValue + 1).fill(0);
    for (let j = shift; j <= nums[i]; j++) {
      next[j] = prefix[j - shift];
    }
    dp = next;
  }
  let total = 0;
  for (const ways of dp) {
    total = (total + ways) % MOD;
  }
  return total;
}

