function countOfPairs(nums) {
  const memo = new Map();
  // Ways to fill positions index.. when arr1 was lastUp at index - 1.
  const ways = (index, lastUp) => {
    if (index === nums.length) return 1;
    const key = index * 1001 + lastUp;
    if (memo.has(key)) return memo.get(key);
    const lastDown = index === 0 ? Infinity : nums[index - 1] - lastUp;
    let count = 0;
    for (let up = lastUp; up <= nums[index]; up++) {
      if (nums[index] - up <= lastDown) count = (count + ways(index + 1, up)) % 1000000007;
    }
    memo.set(key, count);
    return count;
  };
  return ways(0, 0);
}

