function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'small') {
    const n = int(1, 6);
    const top = int(1, 6);
    return [Array.from({ length: n }, () => int(1, top))];
  }
  const n = int(1500, 2000);
  if (rand() < 0.25) {
    return [Array.from({ length: n }, () => int(1, 1000))];
  }
  // Mostly non-increasing values with a few small bumps keep the count non-zero.
  const nums = [];
  let value = int(700, 1000);
  for (let i = 0; i < n; i++) {
    const roll = rand();
    if (roll < 0.02) value = Math.max(1, value - int(1, 3));
    else if (roll < 0.03) value = Math.min(1000, value + int(1, 2));
    nums.push(value);
  }
  return [nums];
}
